import { POOL_LOADERS } from '@/data/pools';
import { toEntry, type PoolEntry, type PoolFile } from './types';

export interface PoolRepository {
  /** Entries of all given pools merged and de-duplicated by title. Missing pools are skipped. */
  entries(poolIds: string[]): PoolEntry[];
  /** True when at least one of the pools has been generated. */
  has(poolIds: string[]): boolean;
  /** Random titles from any available pool (decoys for "Anything" spins). */
  anyTitles(count: number, rng: () => number): string[];
}

/** Reads the JSON pools bundled with the app (generated by tools/build-pools.mjs). */
export class BundledPoolRepository implements PoolRepository {
  private cache = new Map<string, PoolEntry[]>();
  private mergedCache = new Map<string, PoolEntry[]>();

  constructor(private loaders: Record<string, () => PoolFile> = POOL_LOADERS) {}

  private load(id: string): PoolEntry[] {
    const cached = this.cache.get(id);
    if (cached) return cached;
    const loader = this.loaders[id];
    const entries = loader ? loader().items.map(toEntry) : [];
    this.cache.set(id, entries);
    return entries;
  }

  entries(poolIds: string[]): PoolEntry[] {
    const key = poolIds.join('|');
    const cached = this.mergedCache.get(key);
    if (cached) return cached;
    if (poolIds.length === 1) return this.load(poolIds[0] ?? '');
    const seen = new Map<string, PoolEntry>();
    for (const id of poolIds) {
      for (const e of this.load(id)) {
        const prev = seen.get(e.title);
        if (!prev) seen.set(e.title, e);
        else if (e.countries.some((c) => !prev.countries.includes(c))) {
          seen.set(e.title, { ...prev, countries: [...new Set([...prev.countries, ...e.countries])] });
        }
      }
    }
    const merged = [...seen.values()];
    this.mergedCache.set(key, merged);
    return merged;
  }

  has(poolIds: string[]): boolean {
    return poolIds.some((id) => id in this.loaders);
  }

  anyTitles(count: number, rng: () => number): string[] {
    const ids = Object.keys(this.loaders);
    if (!ids.length) return [];
    const out: string[] = [];
    for (let i = 0; i < count; i++) {
      const pool = this.load(ids[Math.floor(rng() * ids.length)] ?? '');
      const pick = pool[Math.floor(rng() * pool.length)];
      if (pick) out.push(pick.title);
    }
    return out;
  }
}
